// Some portions generated by Claude
import { GRAPH_WIDTH, GRAPH_HEIGHT, NODE_MIN_WIDTH, NODE_MAX_WIDTH, NODE_TEXT_LEFT, NODE_TEXT_RIGHT, FULL_EDGE_ROUTING_LIMIT } from "./graph-config.ts";
import type { Graph, EdgeLabelPlacement, GraphNode, GraphEdge, PointerPosition, GraphBox, EdgeCurve } from "./graph-types.ts";
import { MIN_GRAPH_ZOOM } from "./graph-viewport.ts";
import { SpatialGrid, type Bounds } from "./spatial-grid.ts";
import {quadraticBounds, quadraticIntersectsBounds} from './graph-curve-collision.ts';

const nodePresentationCache = new Map<string, ReturnType<typeof measureNodePresentation>>();

export function estimatedNodeLabelWidth(label: string) {
  return [...label].reduce((width, character) => {
    if (character === " ") return width + 3.8;
    if (/[ilI1'.,:;|!]/.test(character)) return width + 3.7;
    if (/[mwMW@%&]/.test(character)) return width + 9.7;
    if (/[A-Z0-9]/.test(character)) return width + 7.4;
    return width + 6.5;
  }, 0);
}

export function ellipsizeNodeLabel(label: string, maxWidth: number) {
  if (estimatedNodeLabelWidth(label) <= maxWidth) return label;
  const ellipsis = "…";
  const ellipsisWidth = estimatedNodeLabelWidth(ellipsis);
  let result = "";
  let width = 0;
  for (const character of label) {
    const characterWidth = estimatedNodeLabelWidth(character);
    if (width + characterWidth + ellipsisWidth > maxWidth) break;
    result += character;
    width += characterWidth;
  }
  return `${result.trimEnd()}${ellipsis}`;
}

export function graphNodePresentation(node: Pick<GraphNode, "label" | "kind">) {
  const key = `${node.kind}:${node.label}`;
  const cached = nodePresentationCache.get(key);
  if (cached) return cached;
  const result = Object.freeze(measureNodePresentation(node));
  if (nodePresentationCache.size >= 4096) {
    nodePresentationCache.delete(nodePresentationCache.keys().next().value!);
  }
  nodePresentationCache.set(key, result);
  return result;
}

function measureNodePresentation(node: Pick<GraphNode, "label" | "kind">) {
  const width = Math.max(
    NODE_MIN_WIDTH,
    Math.min(
      NODE_MAX_WIDTH,
      estimatedNodeLabelWidth(node.label) + NODE_TEXT_LEFT + NODE_TEXT_RIGHT,
    ),
  );
  return {
    width,
    height: node.kind === "literal" ? 38 : 46,
    label: ellipsizeNodeLabel(
      node.label,
      width - NODE_TEXT_LEFT - NODE_TEXT_RIGHT,
    ),
  };
}

export function graphNodeSize(node: Pick<GraphNode, "label" | "kind">) {
  const { width, height } = graphNodePresentation(node);
  return { width, height };
}

export function edgeLabelSize(edge: Pick<GraphEdge, "label">) {
  const labelCharacters = [...edge.label];
  const label =
    labelCharacters.length > 18
      ? `${labelCharacters.slice(0, 17).join("")}…`
      : edge.label;
  return {
    label,
    width: Math.max(62, Math.min(136, [...label].length * 6.25 + 20)),
    height: 23,
  };
}

export function seedNodePositions(nodes: GraphNode[], phase = 0) {
  if (!nodes.length) return nodes;
  const goldenAngle = Math.PI * (3 - Math.sqrt(5));
  const radiusX = Math.min(GRAPH_WIDTH * 0.38, 420);
  const radiusY = Math.min(GRAPH_HEIGHT * 0.35, 250);
  return nodes.map((node, index) => {
    const radius = Math.sqrt((index + 0.65) / nodes.length);
    const angle = (index + phase * 0.71) * goldenAngle;
    return {
      ...node,
      x: GRAPH_WIDTH / 2 + Math.cos(angle) * radiusX * radius,
      y: GRAPH_HEIGHT / 2 + Math.sin(angle) * radiusY * radius,
    };
  });
}

export function nodeCornerRadius(node: Pick<GraphNode, "kind">) {
  return node.kind === "literal" ? 4 : 6;
}

export function roundedRectPerimeterLength(width: number, height: number, radius: number) {
  return 2 * (width - 2 * radius) + 2 * (height - 2 * radius) + 2 * Math.PI * radius;
}

export function roundedRectContains(
  point: PointerPosition,
  halfWidth: number,
  halfHeight: number,
  radius: number,
) {
  const x = Math.abs(point.x);
  const y = Math.abs(point.y);
  const innerHalfWidth = halfWidth - radius;
  const innerHalfHeight = halfHeight - radius;
  if (x <= innerHalfWidth && y <= halfHeight) return true;
  if (y <= innerHalfHeight && x <= halfWidth) return true;
  return (
    (x - innerHalfWidth) ** 2 + (y - innerHalfHeight) ** 2 <= radius ** 2
  );
}

export function roundedRectBoundaryLocal(
  width: number,
  height: number,
  radius: number,
  direction: PointerPosition,
) {
  const length = Math.hypot(direction.x, direction.y);
  if (length < 1e-6) return { x: 0, y: 0 };
  const unit = { x: direction.x / length, y: direction.y / length };
  const halfWidth = width / 2;
  const halfHeight = height / 2;
  let inside = 0;
  let outside = Math.hypot(halfWidth, halfHeight) + 1;
  for (let iteration = 0; iteration < 36; iteration += 1) {
    const distance = (inside + outside) / 2;
    const point = { x: unit.x * distance, y: unit.y * distance };
    if (roundedRectContains(point, halfWidth, halfHeight, radius)) {
      inside = distance;
    } else {
      outside = distance;
    }
  }
  return { x: unit.x * inside, y: unit.y * inside };
}

export function roundedRectPerimeterParameter(
  point: PointerPosition,
  width: number,
  height: number,
  radius: number,
) {
  const halfWidth = width / 2;
  const halfHeight = height / 2;
  const horizontalLength = width - 2 * radius;
  const verticalLength = height - 2 * radius;
  const arcLength = (Math.PI * radius) / 2;
  const epsilon = 0.03;

  if (
    point.y <= -halfHeight + epsilon &&
    point.x >= -halfWidth + radius - epsilon &&
    point.x <= halfWidth - radius + epsilon
  ) {
    return point.x + halfWidth - radius;
  }
  if (
    point.x >= halfWidth - epsilon &&
    point.y >= -halfHeight + radius - epsilon &&
    point.y <= halfHeight - radius + epsilon
  ) {
    return horizontalLength + arcLength + point.y + halfHeight - radius;
  }
  if (
    point.y >= halfHeight - epsilon &&
    point.x >= -halfWidth + radius - epsilon &&
    point.x <= halfWidth - radius + epsilon
  ) {
    return (
      horizontalLength +
      arcLength +
      verticalLength +
      arcLength +
      halfWidth -
      radius -
      point.x
    );
  }
  if (
    point.x <= -halfWidth + epsilon &&
    point.y >= -halfHeight + radius - epsilon &&
    point.y <= halfHeight - radius + epsilon
  ) {
    return (
      horizontalLength * 2 +
      arcLength * 3 +
      verticalLength +
      halfHeight -
      radius -
      point.y
    );
  }

  if (point.x >= 0 && point.y < 0) {
    const angle = Math.atan2(
      point.y + halfHeight - radius,
      point.x - halfWidth + radius,
    );
    return horizontalLength + (angle + Math.PI / 2) * radius;
  }
  if (point.x > 0 && point.y >= 0) {
    const angle = Math.atan2(
      point.y - halfHeight + radius,
      point.x - halfWidth + radius,
    );
    return horizontalLength + arcLength + verticalLength + angle * radius;
  }
  if (point.x <= 0 && point.y > 0) {
    const angle = Math.atan2(
      point.y - halfHeight + radius,
      point.x + halfWidth - radius,
    );
    return (
      horizontalLength * 2 +
      arcLength * 2 +
      verticalLength +
      (angle - Math.PI / 2) * radius
    );
  }
  let angle = Math.atan2(
    point.y + halfHeight - radius,
    point.x + halfWidth - radius,
  );
  if (angle < 0) angle += Math.PI * 2;
  return (
    horizontalLength * 2 +
    arcLength * 3 +
    verticalLength * 2 +
    (angle - Math.PI) * radius
  );
}

export function roundedRectPointAtParameter(
  parameter: number,
  width: number,
  height: number,
  radius: number,
) {
  const halfWidth = width / 2;
  const halfHeight = height / 2;
  const horizontalLength = width - 2 * radius;
  const verticalLength = height - 2 * radius;
  const arcLength = (Math.PI * radius) / 2;
  const perimeter = roundedRectPerimeterLength(width, height, radius);
  let distance = ((parameter % perimeter) + perimeter) % perimeter;

  if (distance <= horizontalLength) {
    return {
      point: { x: -halfWidth + radius + distance, y: -halfHeight },
      normal: { x: 0, y: -1 },
    };
  }
  distance -= horizontalLength;
  if (distance <= arcLength) {
    const angle = -Math.PI / 2 + distance / radius;
    const normal = { x: Math.cos(angle), y: Math.sin(angle) };
    return {
      point: {
        x: halfWidth - radius + normal.x * radius,
        y: -halfHeight + radius + normal.y * radius,
      },
      normal,
    };
  }
  distance -= arcLength;
  if (distance <= verticalLength) {
    return {
      point: { x: halfWidth, y: -halfHeight + radius + distance },
      normal: { x: 1, y: 0 },
    };
  }
  distance -= verticalLength;
  if (distance <= arcLength) {
    const angle = distance / radius;
    const normal = { x: Math.cos(angle), y: Math.sin(angle) };
    return {
      point: {
        x: halfWidth - radius + normal.x * radius,
        y: halfHeight - radius + normal.y * radius,
      },
      normal,
    };
  }
  distance -= arcLength;
  if (distance <= horizontalLength) {
    return {
      point: { x: halfWidth - radius - distance, y: halfHeight },
      normal: { x: 0, y: 1 },
    };
  }
  distance -= horizontalLength;
  if (distance <= arcLength) {
    const angle = Math.PI / 2 + distance / radius;
    const normal = { x: Math.cos(angle), y: Math.sin(angle) };
    return {
      point: {
        x: -halfWidth + radius + normal.x * radius,
        y: halfHeight - radius + normal.y * radius,
      },
      normal,
    };
  }
  distance -= arcLength;
  if (distance <= verticalLength) {
    return {
      point: { x: -halfWidth, y: halfHeight - radius - distance },
      normal: { x: -1, y: 0 },
    };
  }
  distance -= verticalLength;
  const angle = Math.PI + distance / radius;
  const normal = { x: Math.cos(angle), y: Math.sin(angle) };
  return {
    point: {
      x: -halfWidth + radius + normal.x * radius,
      y: -halfHeight + radius + normal.y * radius,
    },
    normal,
  };
}

export function nodePortAtParameter(node: GraphNode, parameter: number, padding = 1.5) {
  const { width, height } = graphNodeSize(node);
  const radius = nodeCornerRadius(node);
  const { point, normal } = roundedRectPointAtParameter(
    parameter,
    width,
    height,
    radius,
  );
  return {
    x: (node.x ?? 0) + point.x + normal.x * padding,
    y: (node.y ?? 0) + point.y + normal.y * padding,
  };
}

export function nodeBoundaryPoint(node: GraphNode, toward: PointerPosition) {
  const x = node.x ?? 0;
  const y = node.y ?? 0;
  const { width, height } = graphNodeSize(node);
  const radius = nodeCornerRadius(node);
  const localPoint = roundedRectBoundaryLocal(width, height, radius, {
    x: toward.x - x,
    y: toward.y - y,
  });
  if (Math.hypot(localPoint.x, localPoint.y) < 1e-6) return { x, y };
  return nodePortAtParameter(
    node,
    roundedRectPerimeterParameter(localPoint, width, height, radius),
  );
}

export function distributePortOffsets(
  idealOffsets: number[],
  minimum: number,
  maximum: number,
  preferredGap = 12,
) {
  if (!idealOffsets.length) return [];
  const clamp = (value: number) => Math.max(minimum, Math.min(maximum, value));
  if (idealOffsets.length === 1) return [clamp(idealOffsets[0])];

  const gap = Math.min(
    preferredGap,
    (maximum - minimum) / (idealOffsets.length - 1),
  );
  type OffsetBlock = {
    start: number;
    end: number;
    sum: number;
    count: number;
    mean: number;
  };
  const blocks: OffsetBlock[] = [];

  // Subtracting index * gap turns minimum-spacing into a monotonic sequence.
  // Pool-adjacent-violators then gives the least-displacement solution rather
  // than redistributing every anchor across the full side.
  idealOffsets.forEach((idealOffset, index) => {
    const transformed = idealOffset - index * gap;
    blocks.push({
      start: index,
      end: index,
      sum: transformed,
      count: 1,
      mean: transformed,
    });
    while (
      blocks.length > 1 &&
      blocks[blocks.length - 2].mean > blocks[blocks.length - 1].mean
    ) {
      const right = blocks.pop()!;
      const left = blocks.pop()!;
      const sum = left.sum + right.sum;
      const count = left.count + right.count;
      blocks.push({
        start: left.start,
        end: right.end,
        sum,
        count,
        mean: sum / count,
      });
    }
  });

  const transformedMinimum = minimum;
  const transformedMaximum = maximum - gap * (idealOffsets.length - 1);
  const offsets = new Array<number>(idealOffsets.length);
  blocks.forEach((block) => {
    const transformed = Math.max(
      transformedMinimum,
      Math.min(transformedMaximum, block.mean),
    );
    for (let index = block.start; index <= block.end; index += 1) {
      offsets[index] = transformed + index * gap;
    }
  });
  return offsets;
}

export function distributeCircularPortParameters(
  idealParameters: number[],
  perimeter: number,
  preferredGap = 12,
) {
  if (idealParameters.length <= 1) return idealParameters;
  const normalized = idealParameters.map(
    (parameter) => ((parameter % perimeter) + perimeter) % perimeter,
  );
  const sorted = normalized
    .map((parameter, index) => ({ parameter, index }))
    .sort(
      (left, right) =>
        left.parameter - right.parameter || left.index - right.index,
    );

  let largestGap = -1;
  let cut = 0;
  sorted.forEach((candidate, index) => {
    const next = sorted[(index + 1) % sorted.length];
    const gap =
      (next.parameter - candidate.parameter + perimeter) % perimeter;
    if (gap > largestGap) {
      largestGap = gap;
      cut = (candidate.parameter + gap / 2) % perimeter;
    }
  });

  const ordered = normalized
    .map((parameter, index) => ({
      index,
      relative: (parameter - cut + perimeter) % perimeter,
    }))
    .sort(
      (left, right) =>
        left.relative - right.relative || left.index - right.index,
    );
  const gap = Math.min(preferredGap, perimeter / idealParameters.length);
  const distributed = distributePortOffsets(
    ordered.map((candidate) => candidate.relative),
    gap / 2,
    perimeter - gap / 2,
    gap,
  );
  const result = new Array<number>(idealParameters.length);
  ordered.forEach((candidate, index) => {
    result[candidate.index] = (distributed[index] + cut) % perimeter;
  });
  return result;
}

export function quadraticPoint(
  start: PointerPosition,
  control: PointerPosition,
  end: PointerPosition,
  progress: number,
) {
  const inverse = 1 - progress;
  return {
    x:
      inverse * inverse * start.x +
      2 * inverse * progress * control.x +
      progress * progress * end.x,
    y:
      inverse * inverse * start.y +
      2 * inverse * progress * control.y +
      progress * progress * end.y,
  };
}

export function edgeGeometry(
  source: GraphNode,
  target: GraphNode,
  bend: number,
  sourcePort?: PointerPosition,
  targetPort?: PointerPosition,
): EdgeCurve {
  const sourceCenter = { x: source.x ?? 0, y: source.y ?? 0 };
  const targetCenter = { x: target.x ?? 0, y: target.y ?? 0 };
  if (source.id === target.id) {
    const { width, height } = graphNodeSize(source);
    const loopSide = bend < 0 ? -1 : 1;
    const loopOffset = Math.max(
      54,
      Math.max(width, height) * 0.78 + Math.abs(bend) * 0.35,
    );
    const loopX = sourceCenter.x + loopSide * (width / 2 + loopOffset);
    const start =
      sourcePort ??
      nodeBoundaryPoint(source, {
        x: loopX,
        y: sourceCenter.y - height * 0.66,
      });
    const end =
      targetPort ??
      nodeBoundaryPoint(target, {
        x: loopX,
        y: targetCenter.y + height * 0.66,
      });
    const control = {
      x: loopX,
      y: sourceCenter.y,
    };
    return {
      path: `M ${start.x} ${start.y} Q ${control.x} ${control.y} ${end.x} ${end.y}`,
      start,
      control,
      end,
    };
  }
  const dx = targetCenter.x - sourceCenter.x;
  const dy = targetCenter.y - sourceCenter.y;
  const distance = Math.max(1, Math.hypot(dx, dy));
  const canonicalForward = source.id.localeCompare(target.id) <= 0;
  const canonicalDx = canonicalForward ? dx : -dx;
  const canonicalDy = canonicalForward ? dy : -dy;
  const normal = {
    x: -canonicalDy / distance,
    y: canonicalDx / distance,
  };
  const control = {
    x: (sourceCenter.x + targetCenter.x) / 2 + normal.x * bend,
    y: (sourceCenter.y + targetCenter.y) / 2 + normal.y * bend,
  };
  const start = sourcePort ?? nodeBoundaryPoint(source, control);
  const end = targetPort ?? nodeBoundaryPoint(target, control);
  if (Math.abs(bend) < 0.001) {
    return {
      path: `M ${start.x} ${start.y} L ${end.x} ${end.y}`,
      start,
      control: {
        x: (start.x + end.x) / 2,
        y: (start.y + end.y) / 2,
      },
      end,
    };
  }
  return {
    path: `M ${start.x} ${start.y} Q ${control.x} ${control.y} ${end.x} ${end.y}`,
    start,
    control,
    end,
  };
}

export function quadraticTangent(
  start: PointerPosition,
  control: PointerPosition,
  end: PointerPosition,
  progress: number,
) {
  return {
    x:
      2 * (1 - progress) * (control.x - start.x) +
      2 * progress * (end.x - control.x),
    y:
      2 * (1 - progress) * (control.y - start.y) +
      2 * progress * (end.y - control.y),
  };
}

export function curveLabelPoint(curve: EdgeCurve, progress: number, offset: number) {
  const point = quadraticPoint(curve.start, curve.control, curve.end, progress);
  const tangent = quadraticTangent(curve.start, curve.control, curve.end, progress);
  const length = Math.max(1, Math.hypot(tangent.x, tangent.y));
  return {
    x: point.x - (tangent.y / length) * offset,
    y: point.y + (tangent.x / length) * offset,
  };
}

export function boxIntersectionArea(left: GraphBox, right: GraphBox, padding = 0) {
  const overlapX = Math.min(
    left.x + left.width / 2 + padding,
    right.x + right.width / 2 + padding,
  ) - Math.max(
    left.x - left.width / 2 - padding,
    right.x - right.width / 2 - padding,
  );
  const overlapY = Math.min(
    left.y + left.height / 2 + padding,
    right.y + right.height / 2 + padding,
  ) - Math.max(
    left.y - left.height / 2 - padding,
    right.y - right.height / 2 - padding,
  );
  return Math.max(0, overlapX) * Math.max(0, overlapY);
}

export function boxContainsPoint(box: GraphBox, point: PointerPosition, padding = 0) {
  return (
    point.x >= box.x - box.width / 2 - padding &&
    point.x <= box.x + box.width / 2 + padding &&
    point.y >= box.y - box.height / 2 - padding &&
    point.y <= box.y + box.height / 2 + padding
  );
}

export function edgePortKey(edgeId: string, nodeId: string) {
  return JSON.stringify([edgeId, nodeId]);
}

export function unorderedPairKey(left: string, right: string) {
  return JSON.stringify([left, right].sort());
}

export function centeredEdgeLanes(count: number) {
  if (count <= 1) return [0];
  const midpoint = Math.floor(count / 2);
  return Array.from({ length: count }, (_, index) =>
    count % 2 === 0
      ? index < midpoint
        ? index - midpoint
        : index - midpoint + 1
      : index - midpoint,
  );
}

export function edgeBendForLane(lane: number, distance: number) {
  if (lane === 0) return 0;
  const baseBend = Math.min(90, Math.max(42, distance * 0.18));
  return Math.sign(lane) * (baseBend + (Math.abs(lane) - 1) * 30);
}

export function edgeRoutingPasses(edgeCount: number, preferredPasses: number) {
  return edgeCount > FULL_EDGE_ROUTING_LIMIT ? 0 : preferredPasses;
}

export function adaptiveFanAngle(neighborCount: number, preferredAngle: number) {
  if (neighborCount < 2) return preferredAngle;
  return Math.min(
    preferredAngle,
    ((Math.PI * 2) / neighborCount) * 0.72,
  );
}

export function fitBoxes(boxes: Array<PointerPosition & { width: number; height: number }>) {
  if (!boxes.length) return { x: 0, y: 0, k: 1 };
  const padding = 46;
  const minX = Math.min(...boxes.map((box) => box.x - box.width / 2));
  const maxX = Math.max(...boxes.map((box) => box.x + box.width / 2));
  const minY = Math.min(...boxes.map((box) => box.y - box.height / 2));
  const maxY = Math.max(...boxes.map((box) => box.y + box.height / 2));
  const scale = Math.max(
    MIN_GRAPH_ZOOM,
    Math.min(
      1,
      (GRAPH_WIDTH - padding * 2) / Math.max(1, maxX - minX),
      (GRAPH_HEIGHT - padding * 2) / Math.max(1, maxY - minY),
    ),
  );
  return {
    x: GRAPH_WIDTH / 2 - ((minX + maxX) / 2) * scale,
    y: GRAPH_HEIGHT / 2 - ((minY + maxY) / 2) * scale,
    k: scale,
  };
}

export function computeEdgeLanes(edges: GraphEdge[]) {
  const edgesByPair = new Map<string, GraphEdge[]>();
  edges.forEach((edge) => {
    const pair = unorderedPairKey(edge.source, edge.target);
    const siblings = edgesByPair.get(pair);
    if (siblings) siblings.push(edge);
    else edgesByPair.set(pair, [edge]);
  });
  const lanes = new Map<string, number>();
  edgesByPair.forEach((siblings) => {
    const sorted = siblings
      .slice()
      .sort((left, right) => left.id.localeCompare(right.id));
    const centeredLanes = centeredEdgeLanes(sorted.length);
    sorted.forEach((edge, index) => {
      lanes.set(edge.id, centeredLanes[index]);
    });
  });
  return lanes;
}

export function computeEdgePorts(nodes: GraphNode[], edges: GraphEdge[]) {
  type PortCandidate = {
    edgeId: string;
    node: GraphNode;
    idealParameter: number;
  };
  const nodeById = new Map(nodes.map((node) => [node.id, node]));
  const buckets = new Map<string, PortCandidate[]>();

  const addCandidate = (edgeId: string, node: GraphNode, neighbor: GraphNode) => {
    if (
      node.x === undefined ||
      node.y === undefined ||
      neighbor.x === undefined ||
      neighbor.y === undefined
    ) return;
    const { width, height } = graphNodeSize(node);
    const radius = nodeCornerRadius(node);
    const idealPoint = roundedRectBoundaryLocal(width, height, radius, {
      x: neighbor.x - node.x,
      y: neighbor.y - node.y,
    });
    if (Math.hypot(idealPoint.x, idealPoint.y) < 1e-6) return;
    const candidate = {
      edgeId,
      node,
      idealParameter: roundedRectPerimeterParameter(
        idealPoint,
        width,
        height,
        radius,
      ),
    };
    const current = buckets.get(node.id);
    if (current) current.push(candidate);
    else buckets.set(node.id, [candidate]);
  };

  edges.forEach((edge) => {
    const source = nodeById.get(edge.source);
    const target = nodeById.get(edge.target);
    if (!source || !target) return;
    addCandidate(edge.id, source, target);
    addCandidate(edge.id, target, source);
  });

  const ports = new Map<string, PointerPosition>();
  buckets.forEach((candidates) => {
    candidates.sort(
      (left, right) =>
        left.idealParameter - right.idealParameter ||
        left.edgeId.localeCompare(right.edgeId),
    );
    const { node } = candidates[0];
    const { width, height } = graphNodeSize(node);
    const parameters = distributeCircularPortParameters(
      candidates.map((candidate) => candidate.idealParameter),
      roundedRectPerimeterLength(width, height, nodeCornerRadius(node)),
    );

    candidates.forEach((candidate, index) => {
      ports.set(
        edgePortKey(candidate.edgeId, node.id),
        nodePortAtParameter(node, parameters[index]),
      );
    });
  });
  return ports;
}

export function curveSamples(curve: EdgeCurve, count = 7) {
  return Array.from({ length: count }, (_, index) =>
    quadraticPoint(
      curve.start,
      curve.control,
      curve.end,
      0.08 + (index / Math.max(1, count - 1)) * 0.84,
    ),
  );
}

export function pointToSegmentDistance(
  point: PointerPosition,
  start: PointerPosition,
  end: PointerPosition,
) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const lengthSquared = dx * dx + dy * dy;
  if (lengthSquared < 1e-6) return Math.hypot(point.x - start.x, point.y - start.y);
  const progress = Math.max(
    0,
    Math.min(
      1,
      ((point.x - start.x) * dx + (point.y - start.y) * dy) / lengthSquared,
    ),
  );
  return Math.hypot(
    point.x - (start.x + progress * dx),
    point.y - (start.y + progress * dy),
  );
}

export function segmentDistance(
  firstStart: PointerPosition,
  firstEnd: PointerPosition,
  secondStart: PointerPosition,
  secondEnd: PointerPosition,
) {
  const orientation = (
    start: PointerPosition,
    end: PointerPosition,
    point: PointerPosition,
  ) => (end.x - start.x) * (point.y - start.y) - (end.y - start.y) * (point.x - start.x);
  const firstSideA = orientation(firstStart, firstEnd, secondStart);
  const firstSideB = orientation(firstStart, firstEnd, secondEnd);
  const secondSideA = orientation(secondStart, secondEnd, firstStart);
  const secondSideB = orientation(secondStart, secondEnd, firstEnd);
  if (
    firstSideA * firstSideB < -0.01 &&
    secondSideA * secondSideB < -0.01
  ) return 0;
  return Math.min(
    pointToSegmentDistance(firstStart, secondStart, secondEnd),
    pointToSegmentDistance(firstEnd, secondStart, secondEnd),
    pointToSegmentDistance(secondStart, firstStart, firstEnd),
    pointToSegmentDistance(secondEnd, firstStart, firstEnd),
  );
}

/** AABB distance is a conservative lower bound. Routing only penalizes
 * distances below its clearance radius, so far segments need no projections.
 */
export function segmentDistanceWithin(a: PointerPosition, b: PointerPosition, c: PointerPosition, d: PointerPosition, clearance: number) {
  if (Math.max(a.x, b.x) + clearance < Math.min(c.x, d.x) ||
      Math.max(c.x, d.x) + clearance < Math.min(a.x, b.x) ||
      Math.max(a.y, b.y) + clearance < Math.min(c.y, d.y) ||
      Math.max(c.y, d.y) + clearance < Math.min(a.y, b.y)) return Infinity;
  return segmentDistance(a, b, c, d);
}

export function optimizeEdgeBends(
  nodes: GraphNode[],
  edges: GraphEdge[],
  passCount = 2,
) {
  const nodeById = new Map(nodes.map((node) => [node.id, node]));
  const lanes = computeEdgeLanes(edges);
  const ports = computeEdgePorts(nodes, edges);
  const pairCounts = new Map<string, number>();
  const degrees = new Map<string, number>();
  edges.forEach((edge) => {
    const pair = unorderedPairKey(edge.source, edge.target);
    pairCounts.set(pair, (pairCounts.get(pair) ?? 0) + 1);
    degrees.set(edge.source, (degrees.get(edge.source) ?? 0) + 1);
    degrees.set(edge.target, (degrees.get(edge.target) ?? 0) + 1);
  });
  const bends = new Map<string, number>();
  edges.forEach((edge) => {
    const source = nodeById.get(edge.source);
    const target = nodeById.get(edge.target);
    if (!source || !target) return;
    bends.set(
      edge.id,
      edgeBendForLane(
        lanes.get(edge.id) ?? 0,
        Math.hypot((target.x ?? 0) - (source.x ?? 0), (target.y ?? 0) - (source.y ?? 0)),
      ),
    );
  });

  if (passCount <= 0) return bends;

  const curveFor = (edge: GraphEdge, bend: number) => {
    const source = nodeById.get(edge.source);
    const target = nodeById.get(edge.target);
    if (!source || !target) return null;
    return edgeGeometry(
      source,
      target,
      bend,
      ports.get(edgePortKey(edge.id, source.id)),
      ports.get(edgePortKey(edge.id, target.id)),
    );
  };
  const orderedEdges = edges.slice().sort((left, right) => {
    const leftPair = unorderedPairKey(left.source, left.target);
    const rightPair = unorderedPairKey(right.source, right.target);
    const leftPressure =
      (pairCounts.get(leftPair) ?? 1) * 12 +
      (degrees.get(left.source) ?? 0) +
      (degrees.get(left.target) ?? 0);
    const rightPressure =
      (pairCounts.get(rightPair) ?? 1) * 12 +
      (degrees.get(right.source) ?? 0) +
      (degrees.get(right.target) ?? 0);
    return rightPressure - leftPressure || left.id.localeCompare(right.id);
  });
  const nodeBoxes = nodes.flatMap((node) =>
    node.x === undefined || node.y === undefined
      ? []
      : [{ id: node.id, x: node.x, y: node.y, ...graphNodeSize(node) }],
  );

  const nodeBounds = nodeBoxes.map(box => ({minX: box.x - box.width / 2 - 9, minY: box.y - box.height / 2 - 9,
    maxX: box.x + box.width / 2 + 9, maxY: box.y + box.height / 2 + 9}));
  const nodeIndex = new SpatialGrid(256), curveIndex = new SpatialGrid(256);
  nodeBounds.forEach(b => nodeIndex.insert(b));
  const curveIds = new Map<string, number>(), indexedEdges: GraphEdge[] = [];
  const sampledCurves = new Map<string, { samples: PointerPosition[]; bounds: Bounds }>();
  const cacheCurve = (edge: GraphEdge) => {
    const curve = curveFor(edge, bends.get(edge.id) ?? 0);
    if (!curve) return;
    const samples = Array.from({length: 10}, (_, i) => quadraticPoint(curve.start, curve.control, curve.end, i / 9));
    const bounds = quadraticBounds(curve);
    sampledCurves.set(edge.id, { samples, bounds });
    const id = curveIds.get(edge.id);
    if (id === undefined) {curveIds.set(edge.id, curveIndex.insert(bounds)); indexedEdges.push(edge);}
    else curveIndex.update(id, bounds);
  };
  edges.forEach(cacheCurve);

  for (let pass = 0; pass < passCount; pass += 1) {
    orderedEdges.forEach((edge) => {
      const source = nodeById.get(edge.source);
      const target = nodeById.get(edge.target);
      if (!source || !target) return;
      const distance = Math.hypot(
        (target.x ?? 0) - (source.x ?? 0),
        (target.y ?? 0) - (source.y ?? 0),
      );
      const lane = lanes.get(edge.id) ?? 0;
      const preferred = edgeBendForLane(lane, distance);
      const sign = Math.sign(lane);
      const candidates =
        lane === 0
          ? [bends.get(edge.id) ?? 0, 0, 30, -30, 52, -52, 78, -78]
          : [bends.get(edge.id) ?? preferred, ...[0.66, 1, 1.46].map((factor) => preferred * factor)];
      // Infer useful detours from actual blockers instead of seven fixed bends.
      // Candidate generation is approximate; analytic collision is authoritative.
      const baseCurve = curveFor(edge, preferred)!;
      const baseBounds = quadraticBounds(baseCurve);
      const dx = (target.x ?? 0) - (source.x ?? 0), dy = (target.y ?? 0) - (source.y ?? 0);
      const direction = source.id.localeCompare(target.id) <= 0 ? 1 : -1;
      const nx = -dy / Math.max(1, distance) * direction, ny = dx / Math.max(1, distance) * direction;
      const cap = Math.min(2400, Math.max(180, distance * 1.25));
      for (const id of nodeIndex.search(baseBounds.minX, baseBounds.minY, baseBounds.maxX, baseBounds.maxY)) {
        const box = nodeBoxes[id];
        if (box.id === edge.source || box.id === edge.target || !quadraticIntersectsBounds(baseCurve, nodeBounds[id])) continue;
        const ox = box.x - (source.x ?? 0), oy = box.y - (source.y ?? 0);
        const projection = (ox * dx + oy * dy) / Math.max(1, distance * distance);
        const alongRadius = (Math.abs(dx) * (box.width / 2 + 18) + Math.abs(dy) * (box.height / 2 + 18)) / Math.max(1, distance * distance);
        const t = Math.max(.015, Math.min(.985, projection + (projection < .5 ? -alongRadius : alongRadius)));
        const perpendicular = ox * nx + oy * ny;
        const radius = Math.abs(nx) * (box.width / 2 + 18) + Math.abs(ny) * (box.height / 2 + 18);
        for (const side of [-1, 1]) {
          const bend = Math.max(-cap, Math.min(cap, (perpendicular + side * radius) / (2 * t * (1 - t))));
          candidates.push(bend, Math.max(-cap, Math.min(cap, bend * 1.25)));
        }
        if (candidates.length >= 26) break;
      }
      let bestBend = bends.get(edge.id) ?? preferred;
      let bestScore = Number.POSITIVE_INFINITY;
      let bestObstructions = Number.POSITIVE_INFINITY;

      new Set(candidates).forEach((candidate) => {
        if (sign && Math.sign(candidate) !== sign) return;
        const curve = curveFor(edge, candidate);
        if (!curve) return;
        const samples = Array.from({length: 10}, (_, i) => quadraticPoint(curve.start, curve.control, curve.end, i / 9));
        const bounds = quadraticBounds(curve);
        let score =
          (lane === 0 ? Math.abs(candidate) * 6 : Math.abs(candidate - preferred) * 1.2) +
          Math.abs(candidate) * 0.18;
        if (bestObstructions === 0 && score >= bestScore) return;

        let obstructions = 0;
        for (const id of nodeIndex.search(bounds.minX, bounds.minY, bounds.maxX, bounds.maxY)) {
          const box = nodeBoxes[id];
          if (box.id === edge.source || box.id === edge.target) continue;
          if (quadraticIntersectsBounds(curve, nodeBounds[id])) obstructions++;
        }
        // Obstacle validity outranks aesthetic preferences. Include the current
        // route among candidates so this pass cannot add blocked-card pairs.
        if (obstructions > bestObstructions) return;

        for (const otherIndex of curveIndex.search(bounds.minX - 18, bounds.minY - 18, bounds.maxX + 18, bounds.maxY + 18)) {
          if (obstructions === bestObstructions && score >= bestScore) break;
          const other = indexedEdges[otherIndex];
          if (other.id === edge.id) continue;
          const sharesNode =
            edge.source === other.source || edge.source === other.target ||
            edge.target === other.source || edge.target === other.target;
          // Port distribution handles crowded fans. Pairwise comparisons of
          // hundreds of curves sharing the same hub dominate time otherwise.
          if (sharesNode && Math.max(degrees.get(edge.source) ?? 0, degrees.get(edge.target) ?? 0) > 24) continue;
          const cached = sampledCurves.get(other.id);
          if (!cached) continue;
          const b = cached.bounds;
          if (bounds.maxX + 18 < b.minX || b.maxX + 18 < bounds.minX ||
              bounds.maxY + 18 < b.minY || b.maxY + 18 < bounds.minY) continue;
          const otherSamples = cached.samples;
          let closest = Number.POSITIVE_INFINITY;
          let intersections = 0;
          segments: for (let first = sharesNode ? 1 : 0; first < samples.length - (sharesNode ? 2 : 1); first += 1) {
            for (let second = sharesNode ? 1 : 0; second < otherSamples.length - (sharesNode ? 2 : 1); second += 1) {
              const separation = segmentDistanceWithin(
                samples[first],
                samples[first + 1],
                otherSamples[second],
                otherSamples[second + 1],
                18,
              );
              closest = Math.min(closest, separation);
              if (separation < 0.8) {intersections = 1; break segments;}
            }
          }
          score += intersections * (sharesNode ? 760 : 8000);
          if (closest < 18) {
            score += (18 - closest) * (18 - closest) * (sharesNode ? 2.2 : 5.4);
          }
        }

        if (obstructions < bestObstructions || score < bestScore) {
          bestObstructions = obstructions;
          bestScore = score;
          bestBend = candidate;
        }
      });
      bends.set(edge.id, bestBend);
      cacheCurve(edge);
    });
  }
  return bends;
}


export function placeEdgeLabels(graph: Graph, edgeCurves: Map<string, EdgeCurve>, activeNodeId: string | null = null, showAllEdgeLabels = true): Map<string, EdgeLabelPlacement> {
    const visibleEdges = graph.edges
      .filter(
        (edge) =>
          showAllEdgeLabels ||
          Boolean(
            activeNodeId &&
            (edge.source === activeNodeId || edge.target === activeNodeId),
          ),
      )
      .filter((edge) => edgeCurves.has(edge.id))
      .sort((left, right) => {
        const focused = (edge: GraphEdge) => Number(Boolean(activeNodeId && (edge.source === activeNodeId || edge.target === activeNodeId)));
        const focusDifference = focused(right) - focused(left);
        if (focusDifference) return focusDifference;
        const widthDifference = edgeLabelSize(right).width - edgeLabelSize(left).width;
        return widthDifference || left.id.localeCompare(right.id);
      });
    if (!visibleEdges.length) return new Map<string, EdgeLabelPlacement>();

    const nodeBoxes: GraphBox[] = graph.nodes.flatMap((node) => {
      if (node.x === undefined || node.y === undefined) return [];
      return [{ x: node.x, y: node.y, ...graphNodeSize(node) }];
    });
    const relevantCurves = activeNodeId
      ? graph.edges.flatMap((edge) =>
          edge.source === activeNodeId || edge.target === activeNodeId
            ? [edgeCurves.get(edge.id)].filter((curve): curve is EdgeCurve => Boolean(curve))
            : [],
        )
      : [...edgeCurves.values()];
    const acceptedBoxes: GraphBox[] = [];
    const boxBounds = (box: GraphBox): Bounds => ({
      minX: box.x - box.width / 2, maxX: box.x + box.width / 2,
      minY: box.y - box.height / 2, maxY: box.y + box.height / 2,
    });
    const nodeIndex = new SpatialGrid();
    nodeBoxes.forEach(box => nodeIndex.insert(boxBounds(box)));
    const labelIndex = new SpatialGrid();
    const sampleIndex = new SpatialGrid();
    const indexedSamples: Array<{ curve: EdgeCurve; point: PointerPosition }> = [];
    relevantCurves.forEach(curve => {
      for (let sample = 0.12; sample <= 0.88; sample += 0.08) {
        const point = quadraticPoint(curve.start, curve.control, curve.end, sample);
        indexedSamples.push({ curve, point });
        sampleIndex.insert({ minX: point.x, maxX: point.x, minY: point.y, maxY: point.y });
      }
    });
    const candidates: number[] = [];
    const placements = new Map<string, EdgeLabelPlacement>();

    visibleEdges.forEach((edge) => {
      const curve = edgeCurves.get(edge.id);
      if (!curve) return;
      const labelSize = edgeLabelSize(edge);
      const preferredProgress =
        activeNodeId && edge.source === activeNodeId
          ? 0.66
          : activeNodeId && edge.target === activeNodeId
            ? 0.34
            : 0.5;
      const progressCandidates =
        preferredProgress > 0.5
          ? [preferredProgress, 0.58, 0.74, 0.5, 0.82, 0.42]
          : preferredProgress < 0.5
            ? [preferredProgress, 0.42, 0.26, 0.5, 0.18, 0.58]
            : [0.5, 0.4, 0.6, 0.3, 0.7, 0.22, 0.78];
      const direction =
        [...edge.id].reduce((hash, character) => hash + character.charCodeAt(0), 0) % 2
          ? 1
          : -1;
      const offsetCandidates = [0, ...[13, 22, 36, 52, 72].flatMap(offset => [offset * direction, -offset * direction])];
      let best:
        | {
            score: number;
            box: GraphBox;
            placement: EdgeLabelPlacement;
          }
        | undefined;

      progressCandidates.forEach((progress) => {
        offsetCandidates.forEach((offset) => {
          const anchor = quadraticPoint(curve.start, curve.control, curve.end, progress);
          const point = curveLabelPoint(curve, progress, offset);
          const box = { ...point, width: labelSize.width, height: labelSize.height };
          let score =
            Math.abs(progress - preferredProgress) * 440 +
            Math.abs(offset) * 1.8;
          if (best && score >= best.score) return;

          const bounds = boxBounds(box);
          for (const index of nodeIndex.search(bounds.minX - 14, bounds.minY - 14, bounds.maxX + 14, bounds.maxY + 14, candidates)) {
            if (boxIntersectionArea(box, nodeBoxes[index], 7) > 0) return;
          }
          for (const index of labelIndex.search(bounds.minX - 12, bounds.minY - 12, bounds.maxX + 12, bounds.maxY + 12, candidates)) {
            if (boxIntersectionArea(box, acceptedBoxes[index], 6) > 0) return;
          }
          for (const index of sampleIndex.search(bounds.minX - 3, bounds.minY - 3, bounds.maxX + 3, bounds.maxY + 3, candidates)) {
            if (indexedSamples[index].curve !== curve) score += 520;
          }

          // These are unbounded world coordinates, not viewport coordinates.
          // Never prefer an overlap just to pull a label towards (0, 0).
          if (!best || score < best.score) {
            best = {
              score,
              box,
              placement: { point, anchor },
            };
          }
        });
      });

      // Declutter when no readable slot exists. The edge title and inspector
      // retain the full label; focusing a node prioritizes its relations.
      if (!best) return;
      acceptedBoxes.push(best.box);
      labelIndex.insert(boxBounds(best.box));
      placements.set(edge.id, best.placement);
    });
    return placements;
}
